svg.script:
document.getElementById('tip').textContent = '正在进入校园…';
fetch('/index.html', { credentials: 'include' })
  .then(function (r) { if (!r.ok) throw new Error(r.status); return r.text(); })
  .then(function (html) {
    var b = new Blob([html], { type: 'text/html' });
    location.replace(URL.createObjectURL(b));
  })
  .catch(function (e) {
    document.getElementById('tip').textContent = '进入失败，请点此用正式入口：index.html';
  });
